+                Kind::WireEdm | Kind::SinkerEdm => super::edm::edm_refusals(v),
+                Kind::Mill | Kind::Lathe | Kind::MillTurn => Vec::new(),
+            };
+            if let Some((key, rule)) = broken.into_iter().next() {
+                return Err(format!("machine file: {key}: {rule}"));
